grader.tests:
assert chunks([], 2) == []
a = [1,2,3,4,5]
assert chunks(a,2) == [[1,2],[3,4],[5]]
assert a == [1,2,3,4,5]
assert chunks([1],4) == [[1]]
for size in (0,-1):
    try: chunks([1],size)
    except ValueError: pass
    else: raise AssertionError('invalid size accepted')

a = {'a': (1,10), 'b':(2,None), 'c':(3,11)}
assert purge(a,10) == {'b':(2,None),'c':(3,11)}
assert len(a) == 3
assert purge({},0) == {}
assert purge(a,9) == a
assert purge(a,9) is not a
